223	const ventus_rtlsim_step_result_t* ventus_rtlsim_t::step() {
224	    step_status.error = contextp->gotFinish() || contextp->gotError();
225	    step_status.time_exceed = contextp->time() >= config.sim_time_max;
226	    step_status.idle = cta->is_idle();
227	    if (step_status.error || step_status.time_exceed) {
228	        return &step_status;
229	    }
230	    bool sim_got_error = false;
231	
232	    //
233	    // clock step
234	    //
235	    contextp->timeInc(HALF_CYCLE_TIME);
236	    dut->clock = !dut->clock;
237	
238	    //
239	    // Delta time before negedge(clk)
240	    // apply outside stimuli to DUT
241	    //
242	    if (dut->clock == 0) {
243	        // Thread-block dispatch to GPU (stimuli)
244	        cta->apply_to_dut(dut);
245	
246	        // Thread-block return from GPU (stimuli)
247	        dut->io_host_rsp_ready = 1;
248	
249	        // Assert Verilated memory IO type: must be VlWide
250	        static_assert(VlIsVlWide<std::decay<decltype(dut->io_mem_rd_data)>::type>::value, "Check io_mem type");
251	        static_assert(VlIsVlWide<std::decay<decltype(dut->io_mem_wr_data)>::type>::value, "Check io_mem type");
252	        static_assert(VlIsVlWide<std::decay<decltype(dut->io_mem_wr_mask)>::type>::value, "Check io_mem type");
253	
254	        // Physical memory access - read
255	        if (dut->io_mem_rd_en) {
256	            uint64_t rd_addr = dut->io_mem_rd_addr;
257	            pmem->read(rd_addr, dut->io_mem_rd_data.data(), dut->io_mem_rd_data.Words * 4);
258	        }
259	        // Physical memory access - write
260	        if (dut->io_mem_wr_en) {
261	            uint64_t wr_addr = dut->io_mem_wr_addr;
262	            bool* mask = new bool[dut->io_mem_wr_mask.Words * 32];
263	            for (int idx = 0; idx < dut->io_mem_wr_mask.Words; idx++) {
264	                uint32_t mask_raw = dut->io_mem_wr_mask[idx];
265	                for (int bit = 0; bit < 32; bit++) {
266	                    mask[bit + idx * 32] = mask_raw & 0x1;
267	                    mask_raw >>= 1;
268	                }
269	            }
270	            if (!pmem->write(wr_addr, dut->io_mem_wr_data.data(), mask, dut->io_mem_wr_data.Words * 4)) {
271	                sim_got_error = true;
272	            }
273	            delete[] mask;
274	        }
275	    }
276	
277	    //
278	    // Delta time before posedge(clk)
279	    // Check for Valid-Ready fire
280	    //
281	    if (dut->clock == 1) {
282	        // Thread-block dispatch to GPU (handshake OK)
283	        if (dut->io_host_req_valid && dut->io_host_req_ready) {
284	            uint32_t wg_id = dut->io_host_req_bits_host_wg_id;
285	            uint32_t wg_idx, kernel_id;
286	            std::string kernel_name;
287	            assert(cta->wg_get_info(kernel_name, kernel_id, wg_idx));
288	            cta->wg_dispatched();
289	            logger->debug(fmt::format(
290	                "block{0:<2} dispatched to GPU (kernel{1:<2} {2} block{3:<2})", wg_id, kernel_id, kernel_name, wg_idx
291	            ));
292	        }
293	        // Thread-block return from GPU (handshake OK)
294	        if (dut->io_host_rsp_valid && dut->io_host_rsp_ready) {
295	            uint32_t wg_id = dut->io_host_rsp_bits_inflight_wg_buffer_host_wf_done_wg_id;
296	            cta->wg_finish(wg_id);
297	        }
298	        dut->io_icache_invalidate = need_icache_invalidate;
299	        need_icache_invalidate = false;
300	    }
301	
302	    //
303	    // Eval
304	    //
305	    dut->eval();
306	    waveform_dump();
307	
308	    //
309	    // Abort?
310	    //
311	    if (g_interrupt) {
312	        destructor(false);
313	        std::exit(130);
314	    }
315	    if (g_aborted) {
316	        destructor(false);
317	        if (g_sigabort_old.has_value()) {
318	            sigaction(SIGABRT, &(g_sigabort_old.value()), nullptr);
319	            g_sigabort_old = std::nullopt;
320	            raise(SIGABRT); // 让进程按默认方式终止，允许Coredump
321	        } else {
322	            std::exit(EXIT_FAILURE);
323	        }
324	    }
325	
326	    //
327	    // Clock output
328	    //
329	    if (contextp->time() % 10000 == 0) {
330	        logger->debug("");
331	    }
332	
333	    //
334	    // snapshot fork
335	    //
336	    step_status.error = sim_got_error || contextp->gotFinish() || contextp->gotError();
337	    step_status.time_exceed = contextp->time() >= config.sim_time_max;
338	    step_status.idle = cta->is_idle();
339	    if (!step_status.time_exceed && !step_status.error && contextp->time() % config.snapshot.time_interval == 0) {
340	        snapshot_fork();
341	    }
342	
343	#ifdef ENABLE_GVM
344	    if (contextp->time() % 2 == 1) {
345	        gvm.getDut();
346	        gvm.gvmStep();
347	    }
348	#endif // ENABLE_GVM
349	
350	    return &step_status;
351	}
352	
353	void ventus_rtlsim_t::destructor(bool snapshot_rollback_forcing) {
354	    uint64_t sim_end_time = contextp->time();
355	    bool need_rollback
356	        = snapshot_rollback_forcing || step_status.error || contextp->gotError() || contextp->gotFinish();
357	
358	    // prints simulation result
359	    if (config.snapshot.enable && snapshots.is_child) { // This is the forked snapshot process
360	        if (need_rollback) {
361	            if (sim_end_time == snapshots.main_exit_time) {
362	                logger->info("SNAPSHOT exited at time {}, OK", sim_end_time);
363	            } else {
364	                logger->error(
365	                    "SNAPSHOT exited at time {}, which differs from the original process (time {})", sim_end_time,
366	                    snapshots.main_exit_time
367	                );
368	            }
369	        } else {
370	            logger->error(
371	                "SNAPSHOT finished NORMALLY at time {}, which differs from the original process", sim_end_time
372	            );
373	        }
374	    } else { // This is the main simulation process
375	        if (need_rollback) {
376	            logger->critical("Simulation exited ABNORMALLY at time {}", sim_end_time);
377	        } else {
378	            logger->info("Simulation finished in {} unit time", sim_end_time);
379	        }
380	    }
381	
382	    if (tfp)
383	        tfp->close();
384	    dut->final();                  // Final model cleanup
385	    contextp->statsPrintSummary(); // Final simulation summary
386	
387	    // invoke snapshot if needed
388	    if (config.snapshot.enable && !snapshots.is_child && snapshots.children_pid.size() != 0 && need_rollback) {
389	        snapshot_rollback(sim_end_time); // Exec snapshot
390	    }
391	    // clear snapshots
392	    if (config.snapshot.enable && snapshots.is_child) {
393	        logger->info("SNAPSHOT process exit... wavefrom dumped as {}", config.snapshot.filename);
394	    } else {
395	        snapshot_kill_all(); // kill unused snapshots in the parent process
396	    }
397	
398	    delete dut;
399	    delete cta;
400	    if (tfp)
401	        delete tfp;
402	    dut = nullptr;
403	    cta = nullptr;
404	    tfp = nullptr;
405	    delete contextp; // log system use this to get time
406	    contextp = nullptr;
407	    g_instances.erase(std::remove(g_instances.begin(), g_instances.end(), this), g_instances.end());
408	}
409	
410	void ventus_rtlsim_t::snapshot_fork() {
411	    if (!config.snapshot.enable || snapshots.is_child)
412	        return;
413	    assert(dut && contextp);
414	
415	    // delete oldest snapshot if needed
416	    if (snapshots.children_pid.size() >= config.snapshot.num_max) {
417	        pid_t oldest = snapshots.children_pid.back();
418	        kill(oldest, SIGKILL);
419	        waitpid(oldest, NULL, 0);
420	        snapshots.children_pid.pop_back();
421	    }
422	    // fork a new snapshot process
423	    // see https://verilator.org/guide/latest/connecting.html#process-level-clone-apis
424	    // see verilator/test_regress/t/t_wrapper_clone.cpp:48
425	    dut->prepareClone(); // prepareClone can be omitted if a little memory leak is ok
426	    pid_t child_pid = fork();
427	    dut->atClone(); // If prepareClone is omitted, call atClone() only in child process
428	    if (child_pid < 0) {
429	        logger->error("SNAPSHOT: failed to fork new child process");
430	        return;
431	    }
432	    if (child_pid != 0) { // for the original process
433	        snapshots.children_pid.push_front(child_pid);
434	        logger->info("SNAPSHOT created, pid={}", child_pid);
435	    } else { // for the fork-child snapshot process
436	        snapshots.is_child = true;
437	        // child process should exit when parent process exits
438	        if (prctl(PR_SET_PDEATHSIG, SIGKILL) == -1) {
439	            perror("prctl(PR_SET_PDEATHSIG)");
440	            std::exit(EXIT_FAILURE);
441	        }
442	        if (getppid() == 1) { // parent process already exited
443	            std::exit(EXIT_FAILURE);
444	        }
445	        // wait for main process
446	        sigset_t set, oldset;
447	        siginfo_t info;
448	        sigemptyset(&set);
449	        sigaddset(&set, SNAPSHOT_WAKEUP_SIGNAL);
450	        sigprocmask(SIG_BLOCK, &set, &oldset);   // Block SIG for using sigwait
451	        sigwaitinfo(&set, &info);                // Wait for snapshot-rollback
452	        sigprocmask(SIG_SETMASK, &oldset, NULL); // Change signal blocking mask back
453	        assert(info.si_signo == SNAPSHOT_WAKEUP_SIGNAL);
454	        // main process invoked snapshot rollback
455	        snapshots.main_exit_time = (uint64_t)(info.si_value.sival_ptr);
456	        logger->info(
457	            "SNAPSHOT is activated, sim_time = {}, origin process exited at time {}", contextp->time(),
458	            snapshots.main_exit_time
459	        );
460	        // create a new waveform dump file
461	        //  delete tfp;             // Cannot do this, or it will block the process
462	        //  (maybe because Vdut.fst was already closed in the parent process?)
463	        tfp = new VerilatedFstC(); // This will cause memory leak for once, but not serious. How to fix it?
464	        dut->trace(tfp, 99);
465	        if (config.snapshot.filename == NULL) {
466	            logger->error(
467	                "snapshot enabled but snapshot.fst filename is NULL, set to default: logs/ventus_rtlsim.snapshot.fst"
468	            );
469	            config.snapshot.filename = "logs/ventus_rtlsim.snapshot.fst";
470	        }
471	        tfp->open(config.snapshot.filename);
472	    }
473	}
474	
475	void ventus_rtlsim_t::snapshot_rollback(uint64_t time) {
476	    if (!config.snapshot.enable || snapshots.is_child)
477	        return;
478	    if (snapshots.children_pid.empty()) {
479	        logger->error("No snapshot for rolling back. Where is the initial snapshot?");
480	        return;
481	    }
482	    assert(dut && contextp);
483	
484	    logger->info(
485	        "SNAPSHOT rollback to {} time-unit ago, pid={}",
486	        time % config.snapshot.time_interval + (snapshots.children_pid.size() - 1) * config.snapshot.time_interval,
487	        snapshots.children_pid.front()
488	    );
489	    assert(sizeof(sigval_t) >= sizeof(contextp->time()));
490	    sigval_t sigval;
491	    sigval.sival_ptr = (void*)(contextp->time());
492	
493	    pid_t child = snapshots.children_pid.back();     // Choose the oldest snapshot
494	    sigqueue(child, SNAPSHOT_WAKEUP_SIGNAL, sigval); // Activate the snapshot
495	    waitpid(child, NULL, 0);                         // Wait for snapshot finished
496	    snapshots.children_pid.pop_back();
497	}
498	
499	void ventus_rtlsim_t::snapshot_kill_all() {
500	    while (!snapshots.children_pid.empty()) {
501	        pid_t child = snapshots.children_pid.back();
502	        kill(child, SIGKILL);
503	        waitpid(child, NULL, 0);
504	        snapshots.children_pid.pop_back();
505	    }
506	    logger->debug("All snapshot process are cleared, OK");
507	}
508	
509	void ventus_rtlsim_t::waveform_dump() const {
510	    // snapshot child process always enables waveform dump
511	    bool is_snapshot = config.snapshot.enable && snapshots.is_child;
512	    if (!config.waveform.enable && !is_snapshot)
513	        return;
514	
515	    assert(contextp && tfp);
516	    uint64_t time = contextp->time();
517	    if (is_snapshot || time >= config.waveform.time_begin && time < config.waveform.time_end) {
518	        tfp->dump(time);
519	    }
520	}
521	
522	void ventus_rtlsim_t::dut_reset() const {
523	    assert(dut && contextp);
524	    contextp->time(0);
525	    dut->io_host_req_valid = 0;
526	    dut->io_host_rsp_ready = 0;
527	    dut->reset = 1;
528	    dut->clock = 0;
529	    dut->eval();
530	    waveform_dump();
531	
532	    contextp->timeInc(HALF_CYCLE_TIME);
533	    dut->clock = 1;
534	    dut->eval();
535	    waveform_dump();
536	
537	    contextp->timeInc(HALF_CYCLE_TIME);
